mapper.select:
SELECT w.* FROM edu_wrong_question w
WHERE w.wrong_question_student_id = #{studentId}
  AND w.wrong_question_question_id = #{questionId}
  AND w.wrong_question_owner_user_id = #{ownerUserId}
LIMIT 1

SELECT w.* FROM edu_wrong_question w
WHERE w.wrong_question_student_id = #{studentId}
  AND w.wrong_question_question_id = #{questionId}
LIMIT 1

SELECT w.wrong_question_id, w.wrong_question_student_id, w.wrong_question_question_id, w.wrong_question_wrong_count, w.wrong_question_mastery_level, w.wrong_question_last_wrong_time, w.wrong_question_last_review_time, w.wrong_question_review_count, w.wrong_question_paper_id, s.student_name AS wrong_question_student_name, s.student_account AS wrong_question_student_account, q.question_stem AS wrong_question_stem, q.question_subject AS wrong_question_subject FROM edu_wrong_question w LEFT JOIN edu_student s ON s.student_no = w.wrong_question_student_id LEFT JOIN edu_question q ON q.question_id = w.wrong_question_question_id
AND w.wrong_question_student_id = #{query.studentId}
AND q.question_subject = #{query.subject}
AND w.wrong_question_mastery_level = #{query.masteryLevel}
AND (w.wrong_question_owner_user_id IS NULL OR w.wrong_question_owner_user_id = #{scope.ownerPredicate})
ORDER BY w.wrong_question_last_wrong_time DESC

SELECT w.* FROM edu_wrong_question w

    w.wrong_question_student_id = #{studentId}
    AND w.wrong_question_status = 1


            AND (w.wrong_question_owner_user_id IS NULL OR w.wrong_question_owner_user_id = #{scope.ownerPredicate})



ORDER BY w.wrong_question_mastery_level ASC, w.wrong_question_last_wrong_time DESC
LIMIT #{count}
